
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lsrpbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lsrpbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.306096875210637e+00, -4.224529207368364e+00, -4.110361825672067e+00, -3.952483408769168e+00, -3.737932104041948e+00, -3.453618310985221e+00, -3.090332651274849e+00, -2.649912465491498e+00, -2.154196441282919e+00, -1.642496235643701e+00, -1.118641314683246e+00, -7.122971611070517e-01, -6.022692683284532e-01, -5.024873249325669e-01, -3.748533249325856e-01, -2.518613768175538e-01, -1.350286323726057e-01, -2.753167731483320e-02, -3.997611680990263e-08, 0.000000000000000e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


